USE aer_synapse_db;
DECLARE @WindowKey NVARCHAR(40) = '@{pipeline().parameters.WindowKey}';
DECLARE @RunStamp NVARCHAR(20) = REPLACE(REPLACE(@WindowKey, '_', ''), '-', '');
DECLARE @BronzePath NVARCHAR(400) = '/bronze/well/window=' + @WindowKey + '/*.parquet';
DECLARE @QuarantineLocation NVARCHAR(400) = '/quarantine/well_rejects/window=' + @WindowKey + '/';
DECLARE @SilverLocation NVARCHAR(400) = '/silver/clean/window=' + @WindowKey + '/';
DECLARE @QuarantineTable NVARCHAR(200) = 'dbo.quarantine_' + @RunStamp;
DECLARE @SilverTable NVARCHAR(200) = 'dbo.silver_clean_' + @RunStamp;

DECLARE @DropSQL NVARCHAR(MAX) = N'IF OBJECT_ID(''' + @QuarantineTable + N''') IS NOT NULL DROP EXTERNAL TABLE ' + @QuarantineTable + N'; IF OBJECT_ID(''' + @SilverTable + N''') IS NOT NULL DROP EXTERNAL TABLE ' + @SilverTable + N';';
EXEC sp_executesql @DropSQL;

DECLARE @QuarantineSQL NVARCHAR(MAX) = N'CREATE EXTERNAL TABLE ' + @QuarantineTable + N' WITH (LOCATION = ''' + @QuarantineLocation + N''', DATA_SOURCE = aer_adls, FILE_FORMAT = parquet_format) AS SELECT UWI_DISPLAY_FORMAT AS WellID, WELL_NAME AS WellName, LICENSE_NO AS LicenceNumber, LICENCE_STATUS AS LicenceStatus, LICENSE_ISSUE_DATE AS LicenceIssueDate, OPERATOR_CODE AS OperatorCode, WELL_TOTAL_DEPTH AS WellTotalDepth, CASE WHEN UWI_DISPLAY_FORMAT IS NULL OR UWI_DISPLAY_FORMAT = '''' THEN ''NULL_UWI'' WHEN LEN(LICENSE_ISSUE_DATE) <> 8 THEN ''INVALID_DATE'' WHEN TRY_CAST(WELL_TOTAL_DEPTH AS DECIMAL(10,2)) < 0 THEN ''NEGATIVE_DEPTH'' ELSE ''OTHER'' END AS RejectReason, GETDATE() AS QuarantineDate FROM OPENROWSET(BULK ''' + @BronzePath + N''', DATA_SOURCE = ''aer_adls'', FORMAT = ''PARQUET'') AS b WHERE UWI_DISPLAY_FORMAT IS NULL OR UWI_DISPLAY_FORMAT = '''' OR LEN(LICENSE_ISSUE_DATE) <> 8 OR TRY_CAST(WELL_TOTAL_DEPTH AS DECIMAL(10,2)) < 0;';
EXEC sp_executesql @QuarantineSQL;

DECLARE @SilverSQL NVARCHAR(MAX) = N'CREATE EXTERNAL TABLE ' + @SilverTable + N' WITH (LOCATION = ''' + @SilverLocation + N''', DATA_SOURCE = aer_adls, FILE_FORMAT = parquet_format) AS SELECT UWI_DISPLAY_FORMAT AS WellID, KEY_LIST_OF_WELLS AS WellKeyID, LTRIM(RTRIM(WELL_NAME)) AS WellName, FIELD_CODE AS FieldCode, POOL_CODE AS PoolCode, LICENSE_NO AS LicenceNumber, LICENCE_STATUS AS LicenceStatus, TRY_CONVERT(DATE, LICENSE_ISSUE_DATE, 112) AS LicenceIssueDate, LICENSEE_CODE AS LicenseeCode, OPERATOR_CODE AS OperatorCode, TRY_CONVERT(DATE, FIN_DRL_DATE, 112) AS FinDrlDate, TRY_CAST(WELL_TOTAL_DEPTH AS DECIMAL(10,2)) AS WellTotalDepth, WELL_STAT_CODE AS WellStatCode, TRY_CONVERT(DATE, WELL_STAT_DATE, 112) AS WellStatDate, CASE WHEN FLUID_SHORT_DESC = ''N/A'' THEN NULL ELSE LTRIM(RTRIM(FLUID_SHORT_DESC)) END AS FluidDesc, CASE WHEN MODE_SHORT_DESC = ''N/A'' THEN NULL ELSE LTRIM(RTRIM(MODE_SHORT_DESC)) END AS ModeDesc, CASE WHEN TYPE_SHORT_DESC = ''N/A'' THEN NULL ELSE LTRIM(RTRIM(TYPE_SHORT_DESC)) END AS TypeDesc, CASE WHEN STRUCTURE_SHORT_DESC = ''N/A'' THEN NULL ELSE LTRIM(RTRIM(STRUCTURE_SHORT_DESC)) END AS StructureDesc, ''BATCH_' + @WindowKey + N''' AS BatchID, GETDATE() AS IngestionDate, ''WellList_incremental'' AS SourceFile FROM OPENROWSET(BULK ''' + @BronzePath + N''', DATA_SOURCE = ''aer_adls'', FORMAT = ''PARQUET'') AS b WHERE UWI_DISPLAY_FORMAT IS NOT NULL AND UWI_DISPLAY_FORMAT <> '''' AND LEN(LICENSE_ISSUE_DATE) = 8 AND TRY_CAST(WELL_TOTAL_DEPTH AS DECIMAL(10,2)) >= 0;';
EXEC sp_executesql @SilverSQL;

@concat('USE aer_synapse_db;
DECLARE @WindowKey NVARCHAR(200)=N''', pipeline().parameters.WindowKey, ''';
DECLARE @RunStamp NVARCHAR(200)=REPLACE(REPLACE(@WindowKey,''_'',''''),''-'','''');
DECLARE @SilverTable SYSNAME=N''dbo.silver_clean_''+@RunStamp;
DECLARE @QuarantineTable SYSNAME=N''dbo.quarantine_''+@RunStamp;
DECLARE @SilverCount BIGINT=0,@QuarantineCount BIGINT=0,@SQL NVARCHAR(MAX);

IF OBJECT_ID(@SilverTable) IS NOT NULL
BEGIN
  SET @SQL=N''SELECT @C=COUNT(*) FROM ''+QUOTENAME(PARSENAME(@SilverTable,2))+N''.''+QUOTENAME(PARSENAME(@SilverTable,1))+N'';'';
  EXEC sp_executesql @SQL,N''@C BIGINT OUTPUT'',@C=@SilverCount OUTPUT;
END;

IF OBJECT_ID(@QuarantineTable) IS NOT NULL
BEGIN
  SET @SQL=N''SELECT @C=COUNT(*) FROM ''+QUOTENAME(PARSENAME(@QuarantineTable,2))+N''.''+QUOTENAME(PARSENAME(@QuarantineTable,1))+N'';'';
  EXEC sp_executesql @SQL,N''@C BIGINT OUTPUT'',@C=@QuarantineCount OUTPUT;
END;

SELECT (@SilverCount+@QuarantineCount) AS BronzeCount,@SilverCount AS SilverCount,@QuarantineCount AS QuarantineCount;')
